import { useState, useEffect } from "react";

export default function OwnedTickets() {
    const [tickets, setTickets] = useState([]);
    const [showModal, setShowModal] = useState(false);
    const [currentTicket, setCurrentTicket] = useState(null);
    const token = localStorage.getItem("token");

    useEffect(() => {
        async function fetchTickets() {
            try {
                const response = await fetch("http://localhost:3001/ownedTickets", {
                    headers: { Authorization: `Bearer ${token}` },
                });
                const data = await response.json();
                if (!response.ok) {
                    alert(`Sikertelen lekérdezés: ${data.message}`);
                } else {
                    setTickets(data.tickets);
                }
            } catch (err) {
                console.log(err);
                alert("Hiba történt a hibajegyek lekérése közben.");
            }
        }
        fetchTickets();
    }, []);

   
    const handleEdit = (ticket) => {
        setCurrentTicket(ticket);
        setShowModal(true);
    };

  
    const handleChange = (e) => {
        setCurrentTicket({
            ...currentTicket,
            [e.target.name]: e.target.value,
        });
    };

    
    const handleSave = async () => {
        try {
            const response = await fetch("http://localhost:3001/changeTickets", {
                method: "PUT",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({
                    title: currentTicket.title,
                    place: currentTicket.place,
                    description: currentTicket.description,
                }),
            });
            const data = await response.json();
            if (!response.ok) {
                alert(`Sikertelen módosítás: ${data.message}`);
            } else {
                alert("Sikeres módosítás!");
                setShowModal(false);
            }
        } catch (err) {
            console.log(err);
            alert("Hiba történt a módosítás során.");
        }
    };

    return (
        <div className="container">
            <div className="card text-center">
                {tickets.length ? tickets.map((ticket) => (
                    <div key={ticket.urgentid} className="card mb-3">
                        <div className="card-header">{ticket.urgentid}</div>
                        <div className="card-body">
                            <h5 className="card-title">{ticket.title}</h5>
                            <h7 className="card-title">{ticket.place}</h7>
                            <p className="card-text">{ticket.description}</p>
                            <h6 className="card-title">{ticket.userid}</h6>
                            <a href="#" className="btn btn-success me-2">Kiosztás</a>
                            <button className="btn btn-primary me-2" onClick={() => handleEdit(ticket)}>Módosítás</button>
                            <a href="#" className="btn btn-danger">Törlés</a>
                        </div>
                        <div className="card-footer text-body-secondary">{ticket.formatted_created_at}</div>
                    </div>
                )) : (<p>Nincsenek hibajegyeid.</p>)}
            </div>

            {/* Modal */}
            {showModal && currentTicket && (
                <div className="modal show d-block" tabIndex="-1">
                    <div className="modal-dialog">
                        <div className="modal-content">
                            <div className="modal-header">
                                <h5 className="modal-title">Ticket módosítása</h5>
                                <button type="button" className="btn-close" onClick={() => setShowModal(false)}></button>
                            </div>
                            <div className="modal-body">
                                <div className="mb-3">
                                    <label className="form-label">Cím</label>
                                    <input
                                        type="text"
                                        className="form-control"
                                        name="title"
                                        value={currentTicket.title}
                                        onChange={handleChange}
                                    />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">Helyszín</label>
                                    <input
                                        type="text"
                                        className="form-control"
                                        name="place"
                                        value={currentTicket.place}
                                        onChange={handleChange}
                                    />
                                </div>
                                <div className="mb-3">
                                    <label className="form-label">Leírás</label>
                                    <textarea
                                        className="form-control"
                                        name="description"
                                        value={currentTicket.description}
                                        onChange={handleChange}
                                    ></textarea>
                                </div>
                            </div>
                            <div className="modal-footer">
                                <button className="btn btn-secondary" onClick={() => setShowModal(false)}>Mégse</button>
                                <button className="btn btn-primary" onClick={handleSave}>Mentés</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}
